type Result<T, E = string> =
  | { ok: true; value: T }
  | { ok: false; error: E };

const ok = <T>(value: T): Result<T, never> => ({ ok: true, value });
const err = <E>(error: E): Result<never, E> => ({ ok: false, error });

function parsePort(raw: string): Result<number, 'empty' | 'not-a-number' | 'out-of-range'> {
  if (!raw.trim()) return err('empty');
  const n = Number(raw);
  if (Number.isNaN(n)) return err('not-a-number');
  if (n < 1 || n > 65535) return err('out-of-range');
  return ok(n);
}

function map<T, U, E>(r: Result<T, E>, fn: (v: T) => U): Result<U, E> {
  return r.ok ? ok(fn(r.value)) : r;
}

function flatMap<T, U, E>(r: Result<T, E>, fn: (v: T) => Result<U, E>): Result<U, E> {
  return r.ok ? fn(r.value) : r;
}

const result = flatMap(parsePort('8080'), (port) =>
  port === 443 ? err('reserved') as Result<number, 'reserved'> : ok(port)
);

type CsvRow = { id: string; amount: number };
type ParseError = { row: number; reason: string };

function parseRow(line: string, rowNum: number): Result<CsvRow, ParseError> {
  const parts = line.split(',');
  if (parts.length < 2) return err({ row: rowNum, reason: 'too few columns' });
  const amount = Number(parts[1]);
  if (Number.isNaN(amount)) return err({ row: rowNum, reason: 'bad amount' });
  return ok({ id: parts[0], amount });
}

// Import loop — no try/catch per row
let failures = 0;
for (const [i, line] of lines.entries()) {
  const r = parseRow(line, i + 1);
  if (!r.ok) { failures++; log(r.error); continue; }
  batch.push(r.value);
}

async function createUser(body: unknown): Promise<Result<User, ValidationError>> {
  const parsed = validateCreateUser(body);
  if (!parsed.ok) return parsed;
  try {
    const user = await db.insertUser(parsed.value);
    return ok(user);
  } catch (e: unknown) {
    return err({ kind: 'db', message: toError(e).message });
  }
}

// Express edge — single throw conversion
app.post('/users', async (req, res) => {
  const r = await createUser(req.body);
  if (!r.ok) return res.status(400).json(r.error);
  res.status(201).json(r.value);
});
